import java.util.Arrays;
class GymMember{protected String memberId;protected int monthlyFee;private int[] lateFeeHistory=new int[10];private int feeCount;public GymMember(String id,int fee){if(id==null||id.trim().length()<4||fee<=0)throw new IllegalArgumentException("Invalid member details");memberId=id;monthlyFee=fee;}protected void chargeLateFee(int n){if(feeCount<lateFeeHistory.length)lateFeeHistory[feeCount++]=n;}public int[] getLateFeeHistory(){return Arrays.copyOf(lateFeeHistory,feeCount);}public int getTotalLateFees(){int t=0;for(int i=0;i<feeCount;i++)t+=lateFeeHistory[i];return t;}}
class PremiumMember extends GymMember{private String trainerName;public PremiumMember(String id,int fee,String t){super(id,fee);trainerName=t;}protected void chargeLateFee(int n){super.chargeLateFee(n/2);}}
public class LateFeeLedger{public static void main(String[] args){PremiumMember p=new PremiumMember("MEM5",2000,"Coach Riya");p.chargeLateFee(200);System.out.println(p.getTotalLateFees());int[] h=p.getLateFeeHistory();h[0]=999;System.out.println(Arrays.toString(p.getLateFeeHistory()));}}